/**
 * QiLin host shim for the DSH typert-protocol base class (H5-d slice 2).
 * The plugin's TypertRemoteService subclasses register themselves into the
 * plugin ctx; the runtime mounts service-keyed dispatch routes over the
 * collected instances. Only the (ctx, service) constructor contract is
 * needed by dsh-file-review-tab's FileReviewService.
 */
export class TypertRemoteService {
  constructor(ctx, service) {
    this.ctx = ctx;
    this.service = service;
    if (Array.isArray(ctx.__typertServices)) {
      ctx.__typertServices.push({ service, instance: this });
    }
  }
}
